/**
 * sidebar/worktree —— worktree switcher（宿主 SessionSidebar worktree 区块 1:1 复制）。
 * 行按钮（当前 worktree/分支 + main 标 + 数量）+ 下拉（过滤/切换/移除/强制移除确认/
 * 新建 worktree 输入）。状态与 handler 全部由 SidebarDock 持有（与宿主同构）。
 */
import type { RefObject } from "react";
import { t } from "../host-shim";
import { displayCwd } from "./pure";
import { AnimatedDropdown, PathLabel } from "./parts";

export interface WorktreeEntry {
  path: string;
  branch?: string;
  isMain?: boolean;
}

export interface WorktreeState {
  forCwd: string;
  projectRoot: string;
  projectKey: string;
  isGit: boolean;
  isTopLevel: boolean;
  currentWorktreePath: string | null;
  worktrees: WorktreeEntry[];
}

export interface WorktreeProps {
  worktreeState: WorktreeState;
  selectedCwd: string | null;
  homeDir: string;
  searchOpen: boolean;
  showWorktreeSwitcher: boolean;
  worktreeGuide: { label: string; title: string } | null;
  worktreeLoading: boolean;
  currentWorktree: WorktreeEntry | undefined;
  currentWorktreePath: string | null;
  wtDropdownOpen: boolean;
  setWtDropdownOpen: (v: boolean | ((prev: boolean) => boolean)) => void;
  wtFilter: string;
  setWtFilter: (v: string) => void;
  wtNewOpen: boolean;
  setWtNewOpen: (v: boolean | ((prev: boolean) => boolean)) => void;
  wtNewBranch: string;
  setWtNewBranch: (v: string) => void;
  wtError: string | null;
  setWtError: (v: string | null) => void;
  wtBusy: boolean;
  wtConfirmRemove: string | null;
  setWtConfirmRemove: (v: string | null) => void;
  wtNewInputRef: RefObject<HTMLInputElement>;
  wtDropdownRef: RefObject<HTMLDivElement>;
  onSelectWorktree: (path: string) => void;
  onRemoveWorktree: (path: string, force: boolean) => void;
  onCreateWorktree: () => void;
}

export function SidebarWorktreeSwitcher(p: WorktreeProps) {
  if (!p.searchOpen && p.showWorktreeSwitcher) {
    if (!p.worktreeState) return null;
    const showWtFilter = p.worktreeState.worktrees.length >= 8;
    const visibleWorktrees = showWtFilter && p.wtFilter.trim()
      ? p.worktreeState.worktrees.filter((w) =>
          (w.branch ?? displayCwd(w.path, p.homeDir)).toLowerCase().includes(p.wtFilter.trim().toLowerCase()))
      : p.worktreeState.worktrees;
    return (
      <div ref={p.wtDropdownRef} style={{ position: "relative", marginTop: 6 }}>
        <button
          onClick={() => p.setWtDropdownOpen((v) => !v)}
          title={p.currentWorktree ? t("sidebar.switchWorktreeTitle", { path: p.currentWorktree.path }) : t("sidebar.switchWorktree")}
          style={{
            width: "100%",
            height: 29,
            boxSizing: "border-box",
            display: "flex",
            alignItems: "center",
            gap: 6,
            padding: "0 10px",
            background: "var(--bg-hover)",
            border: "1px solid var(--border)",
            borderRadius: 7,
            cursor: "pointer",
            fontSize: 11,
            lineHeight: 1.35,
            color: "var(--text-muted)",
            textAlign: "left",
          }}
        >
          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0, color: p.currentWorktree && !p.currentWorktree.isMain ? "var(--accent)" : "var(--text-dim)" }}>
            <line x1="6" y1="3" x2="6" y2="15" />
            <circle cx="18" cy="6" r="3" />
            <circle cx="6" cy="18" r="3" />
            <path d="M18 9a9 9 0 0 1-9 9" />
          </svg>
          <PathLabel
            text={p.currentWorktree ? (p.currentWorktree.branch ?? displayCwd(p.currentWorktree.path, p.homeDir)) : "…"}
            style={{ flex: 1, fontFamily: "var(--font-mono)", color: "var(--text)" }}
          />
          {p.currentWorktree?.isMain && (
            <span style={{ flexShrink: 0, color: "var(--text-dim)", fontSize: 10 }}>{t("sidebar.main")}</span>
          )}
          {p.worktreeState.worktrees.length > 1 && (
            <span style={{ flexShrink: 0, color: "var(--text-dim)", fontSize: 10 }}>
              {p.worktreeState.worktrees.length}
            </span>
          )}
          <svg width="9" height="9" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
            <polyline points="2 3.5 5 6.5 8 3.5" />
          </svg>
        </button>

        <AnimatedDropdown
          open={p.wtDropdownOpen}
          style={{
            position: "absolute",
            top: "calc(100% + 4px)",
            left: 0,
            right: 0,
            zIndex: 100,
            background: "var(--bg)",
            border: "1px solid var(--border)",
            borderRadius: 8,
            boxShadow: "0 6px 20px rgba(0,0,0,0.10)",
            overflow: "hidden",
          }}
        >
          {showWtFilter && (
            <div style={{ padding: "6px 8px", borderBottom: "1px solid var(--border)" }}>
              <input
                value={p.wtFilter}
                onChange={(e) => p.setWtFilter(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Escape") {
                    p.setWtFilter("");
                    p.setWtDropdownOpen(false);
                  }
                }}
                placeholder={t("sidebar.filterWorktrees")}
                autoFocus
                style={{
                  width: "100%",
                  fontSize: 11,
                  fontFamily: "var(--font-mono)",
                  padding: "5px 8px",
                  border: "1px solid var(--border)",
                  borderRadius: 5,
                  outline: "none",
                  background: "var(--bg)",
                  color: "var(--text)",
                  boxSizing: "border-box",
                }}
              />
            </div>
          )}
          <div style={{ maxHeight: "min(40vh, 300px)", overflowY: "auto" }}>
            {visibleWorktrees.map((wt) => {
              const isCurrent = wt.path === p.currentWorktreePath;
              if (p.wtConfirmRemove === wt.path) {
                return (
                  <div key={wt.path} style={{ display: "flex", alignItems: "center", gap: 6, padding: "7px 10px", borderBottom: "1px solid var(--border)", background: "rgba(239,68,68,0.06)" }}>
                    <span style={{ flex: 1, fontSize: 11, color: "var(--text)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {t("sidebar.forceRemoveCheckout")}
                    </span>
                    <button
                      onClick={() => p.onRemoveWorktree(wt.path, true)}
                      disabled={p.wtBusy}
                      style={{ padding: "3px 9px", background: "#ef4444", border: "none", borderRadius: 5, color: "#fff", fontSize: 11, fontWeight: 600, cursor: "pointer", flexShrink: 0 }}
                    >
                      {t("sidebar.force")}
                    </button>
                    <button
                      onClick={() => p.setWtConfirmRemove(null)}
                      style={{ padding: "3px 9px", background: "var(--bg-hover)", border: "1px solid var(--border)", borderRadius: 5, color: "var(--text-muted)", fontSize: 11, cursor: "pointer", flexShrink: 0 }}
                    >
                      {t("sidebar.cancel")}
                    </button>
                  </div>
                );
              }
              return (
                <div
                  key={wt.path}
                  className="wt-row"
                  style={{ display: "flex", alignItems: "center", borderBottom: "1px solid var(--border)" }}
                >
                  <button
                    onClick={() => p.onSelectWorktree(wt.path)}
                    title={wt.path}
                    style={{
                      flex: 1,
                      minWidth: 0,
                      display: "flex",
                      alignItems: "center",
                      gap: 7,
                      padding: "8px 10px",
                      background: "var(--bg)",
                      border: "none",
                      color: isCurrent ? "var(--text)" : "var(--text-muted)",
                      cursor: "pointer",
                      textAlign: "left",
                      fontSize: 11,
                      fontFamily: "var(--font-mono)",
                    }}
                  >
                    {isCurrent ? (
                      <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="var(--accent)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
                        <polyline points="1.5 5 4 7.5 8.5 2.5" />
                      </svg>
                    ) : (
                      <span style={{ width: 10, flexShrink: 0 }} />
                    )}
                    <PathLabel text={wt.branch ?? displayCwd(wt.path, p.homeDir)} style={{ flex: 1 }} />
                    {wt.isMain && <span style={{ flexShrink: 0, color: "var(--text-dim)", fontSize: 10 }}>{t("sidebar.main")}</span>}
                  </button>
                  {!wt.isMain && (
                    <button
                      onClick={() => p.onRemoveWorktree(wt.path, false)}
                      disabled={p.wtBusy}
                      title={t("sidebar.removeWorktreeTitle", { path: wt.path })}
                      style={{
                        display: "flex", alignItems: "center", justifyContent: "center",
                        width: 34, height: 28, padding: 0, marginRight: 4,
                        background: "none", border: "none",
                        color: "var(--text-dim)", cursor: "pointer",
                        borderRadius: 5, flexShrink: 0,
                        transition: "color 0.12s, background 0.12s",
                      }}
                      onMouseEnter={(e) => { e.currentTarget.style.color = "#ef4444"; e.currentTarget.style.background = "rgba(239,68,68,0.08)"; }}
                      onMouseLeave={(e) => { e.currentTarget.style.color = "var(--text-dim)"; e.currentTarget.style.background = "none"; }}
                    >
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <polyline points="3 6 5 6 21 6" />
                        <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
                        <path d="M10 11v6M14 11v6" />
                        <path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2" />
                      </svg>
                    </button>
                  )}
                </div>
              );
            })}
            {showWtFilter && visibleWorktrees.length === 0 && p.wtFilter.trim() && (
              <div style={{ padding: "8px 10px", fontSize: 11, color: "var(--text-dim)" }}>{t("sidebar.noMatchingWorktrees")}</div>
            )}
          </div>

          {!p.wtNewOpen ? (
            <button
              onClick={(e) => {
                e.stopPropagation();
                p.setWtNewOpen(true);
                p.setWtError(null);
                setTimeout(() => p.wtNewInputRef.current?.focus(), 0);
              }}
              title={t("sidebar.createWorktreeTitle")}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 7,
                width: "100%",
                padding: "8px 10px",
                background: "none",
                border: "none",
                color: "var(--text-muted)",
                cursor: "pointer",
                textAlign: "left",
                fontSize: 11,
              }}
            >
              <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" style={{ flexShrink: 0 }}>
                <line x1="5" y1="1" x2="5" y2="9" />
                <line x1="1" y1="5" x2="9" y2="5" />
              </svg>
              <span>{t("sidebar.newWorktree")}</span>
            </button>
          ) : (
            <div style={{ padding: "6px 8px" }}>
              <input
                ref={p.wtNewInputRef}
                value={p.wtNewBranch}
                onChange={(e) => {
                  p.setWtNewBranch(e.target.value);
                  p.setWtError(null);
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    p.onCreateWorktree();
                  }
                  if (e.key === "Escape") {
                    p.setWtNewOpen(false);
                    p.setWtNewBranch("");
                    p.setWtError(null);
                  }
                }}
                placeholder={t("sidebar.branchName")}
                style={{
                  width: "100%",
                  fontSize: 11,
                  fontFamily: "var(--font-mono)",
                  padding: "5px 8px",
                  border: "1px solid var(--accent)",
                  borderRadius: 5,
                  outline: "none",
                  background: "var(--bg)",
                  color: "var(--text)",
                  boxSizing: "border-box",
                }}
              />
              <div style={{ display: "flex", gap: 5, marginTop: 5 }}>
                <button
                  onClick={() => p.onCreateWorktree()}
                  disabled={p.wtBusy || !p.wtNewBranch.trim()}
                  style={{
                    flex: 1,
                    padding: "4px 0",
                    background: "var(--accent)",
                    border: "none",
                    borderRadius: 5,
                    color: "#fff",
                    fontSize: 11,
                    fontWeight: 600,
                    cursor: p.wtBusy || !p.wtNewBranch.trim() ? "not-allowed" : "pointer",
                    opacity: p.wtBusy || !p.wtNewBranch.trim() ? 0.65 : 1,
                  }}
                >
                  {p.wtBusy ? t("sidebar.creating") : t("sidebar.create")}
                </button>
                <button
                  onClick={() => { p.setWtNewOpen(false); p.setWtNewBranch(""); p.setWtError(null); }}
                  style={{
                    flex: 1,
                    padding: "4px 0",
                    background: "var(--bg-hover)",
                    border: "1px solid var(--border)",
                    borderRadius: 5,
                    color: "var(--text-muted)",
                    fontSize: 11,
                    cursor: "pointer",
                  }}
                >
                  {t("sidebar.cancel")}
                </button>
              </div>
            </div>
          )}
          {p.wtError && (
            <div style={{
              padding: "5px 10px 8px",
              color: "#dc2626",
              fontSize: 11,
              lineHeight: 1.35,
              overflowWrap: "anywhere",
            }}>
              {p.wtError}
            </div>
          )}
        </AnimatedDropdown>
      </div>
    );
  }

  // Inactive guide row（非仓库根/检查中提示行）
  if (!p.searchOpen && p.worktreeGuide) {
    return (
      <button
        type="button"
        aria-disabled="true"
        tabIndex={-1}
        title={p.worktreeGuide.title}
        style={{
          width: "100%",
          height: 29,
          boxSizing: "border-box",
          marginTop: 6,
          display: "flex",
          alignItems: "center",
          gap: 6,
          padding: "0 10px",
          border: "1px solid var(--border)",
          borderRadius: 7,
          background: "var(--bg-hover)",
          color: "var(--text-dim)",
          fontSize: 11,
          lineHeight: 1.35,
          whiteSpace: "nowrap",
          textAlign: "left",
          cursor: "default",
          opacity: 0.82,
        }}
      >
        <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
          <line x1="6" y1="3" x2="6" y2="15" />
          <circle cx="18" cy="6" r="3" />
          <circle cx="6" cy="18" r="3" />
          <path d="M18 9a9 9 0 0 1-9 9" />
        </svg>
        <span style={{ overflow: "hidden", textOverflow: "ellipsis" }}>{p.worktreeGuide.label}</span>
      </button>
    );
  }

  return null;
}
