/**
 * _shared/ext-float-dock.ts — aiti-float dock 状态机的扩展侧薄订阅层（方案
 * aiti-web-ext-float-dock-plan.md §3.3/§6）。被各扩展 vite 构建内联进 bundle
 * （cursor-cli-store 先例）：aiti-float 在场时委托 window.__piweFloat 状态机；
 * 缺席时用本地降级 store（同语义）——纯嵌入形态照常可用（dock 方案 §8 #15）。
 *
 * 红线（dock 方案 §3.5）：gate 是唯一渲染开关——扩展不得再以自有 state 直接
 * 控制浮窗/嵌入两 face 的显隐。
 */
import { useEffect, useState, createElement as h } from "react";

export type DockZone = "sidebar-explorer" | "right-panel";
export type PresentState = "closed" | "floating" | `docked:${string}`;

const ITEM_KEY_GLOBAL = "__piweFloat";
const CHANGE_EVENT = "piwe-float-present-change";
const DOCKPREF_KEY = (k: string) => `pi-web:ext-float:dockpref:v1:${k}`;

type FloatApi = {
  present(k: string, mode: "open" | "float" | `dock:${string}` | "close"): void;
  presented(k: string): PresentState;
  onPresentChange(cb: (detail: { key: string; state: PresentState }) => void): () => void;
  dockPref(k: string): string | null;
};

function floatApi(): FloatApi | null {
  const api = (window as any)[ITEM_KEY_GLOBAL] as FloatApi | undefined;
  return api && typeof api.present === "function" ? api : null;
}

/* ── 降级 store（未装 aiti-float）：无浮窗形态，open 直达停靠（嵌入可用） ── */
const localStates = new Map<string, PresentState>();
const localSubs = new Set<(detail: { key: string; state: PresentState }) => void>();

function localPresent(k: string, mode: "open" | "float" | `dock:${string}` | "close") {
  const prev = localStates.get(k) ?? "closed";
  let next: PresentState = prev;
  if (mode === "open") {
    // 降级 = 完全回到现状行为：面板自绘浮窗（无 ⇱ 无停靠），嵌入 face 不渲染
    next = "floating";
  } else if (mode === "float") next = "floating";
  else if (mode === "close") next = "closed";
  else if (mode.startsWith("dock:")) next = mode as PresentState;
  if (next === prev) return;
  localStates.set(k, next);
  const detail = { key: k, state: next };
  for (const cb of localSubs) { try { cb(detail); } catch { /* ignore */ } }
  try { window.dispatchEvent(new CustomEvent(CHANGE_EVENT, { detail })); } catch { /* ignore */ }
}

/* ── 公共 API ── */

export function present(k: string, mode: "open" | "float" | `dock:${string}` | "close"): void {
  const api = floatApi();
  if (api) { api.present(k, mode); return; }
  localPresent(k, mode);
}

export function presentState(k: string): PresentState {
  const api = floatApi();
  if (api) return api.presented(k) ?? "closed";
  return localStates.get(k) ?? "closed";
}

export function onPresentChange(cb: (detail: { key: string; state: PresentState }) => void): () => void {
  const api = floatApi();
  if (api) return api.onPresentChange(cb);
  localSubs.add(cb);
  return () => localSubs.delete(cb);
}

export function dockPref(k: string): string | null {
  const api = floatApi();
  if (api) return api.dockPref(k) ?? null;
  try { return localStorage.getItem(DOCKPREF_KEY(k)); } catch { return null; }
}

/* ── 语义糖 ── */

/** docked 态重复 open 的容器 flash 提示（方案 §3.2：不开第二个，提示面板在哪）。
 *  定位 DockBody 根上的 data-ext-item 标注（自删 CSS class，零宿主逻辑）。 */
function flashDockContainer(k: string): void {
  try {
    const el = document.querySelector(`[data-ext-float-dock-body="${k}"]`);
    if (!el) return;
    el.classList.remove("piwe-dock-flash");
    // 触发 reflow 重启动画
    void (el as HTMLElement).offsetWidth;
    el.classList.add("piwe-dock-flash");
    setTimeout(() => el.classList.remove("piwe-dock-flash"), 2000);
  } catch { /* ignore */ }
}

export function openFloat(k: string) {
  // docked 态幂等 open：不开第二个，flash 提示（方案 §3.2）；float 状态机内部同样幂等
  const st = presentState(k);
  if (st.startsWith("docked:")) flashDockContainer(k);
  present(k, "open");
}

// 降级命令监听：未装 aiti-float 时由本层响应宿主命令事件（TabBar ✕ 等）；
// float 在场时由 float 的监听处理（本层不重复执行）
if (typeof window !== "undefined") {
  try {
    window.addEventListener("piwe-float-present-command", ((e: CustomEvent<{ key: string; mode: "open" | "float" | `dock:${string}` | "close" }>) => {
      if (floatApi()) return; // float 在场 → float 的监听已处理
      if (!e.detail || !e.detail.key || !e.detail.mode) return;
      localPresent(e.detail.key, e.detail.mode);
    }) as EventListener);
  } catch { /* ignore */ }
}
export function dockTo(k: string, zone: DockZone) { present(k, `dock:${zone}`); }
export function undockToFloat(k: string) { present(k, "float"); }
export function closePanel(k: string) { present(k, "close"); }

/* flash 样式（一次性注入；docked 态重复 open 的容器高亮，2s 自删 class） */
if (typeof document !== "undefined" && !document.getElementById("piwe-dock-flash-css")) {
  try {
    const st = document.createElement("style");
    st.id = "piwe-dock-flash-css";
    st.textContent = "@keyframes piwe-dock-flash-kf { 0%,100% { box-shadow: none; } 30% { box-shadow: inset 0 0 0 2px var(--accent, #2563eb); } }"
      + ".piwe-dock-flash { animation: piwe-dock-flash-kf 2s ease; }";
    document.head.appendChild(st);
  } catch { /* ignore */ }
}

/* ── React 绑定（各扩展 bundle 自带 react；不引 react 的调用方直接用下面的 usePresent/useGate/DockBody） ── */

export function usePresent(itemKey: string): PresentState {
  const [state, setState] = useState<PresentState>(() => presentState(itemKey));
  useEffect(() => {
    setState(presentState(itemKey));
    return onPresentChange((d) => { if (d.key === itemKey) setState(d.state); });
  }, [itemKey]);
  return state;
}

/** 渲染门控（结构性防双开）：face="float" → 仅浮窗态渲染；face={dock:zone} → 仅对应嵌入态渲染。 */
export function useGate(itemKey: string, face: "float" | { dock: DockZone }): boolean {
  const state = usePresent(itemKey);
  if (face === "float") return state === "floating";
  return state === `docked:${face.dock}`;
}

/* ── DockBody：嵌入块标准结构（头行 标题+⇲[+✕] + 滚动体） ── */
export function DockBody(props: {
  itemKey: string;
  zone: DockZone;
  title?: string;
  /** "section"：标题+⇲+✕（侧栏 DockSection）；"tab"：标题+⇲（右栏 TabBar 已有 ✕，防双 ✕） */
  chrome?: "section" | "tab";
  children: any;
}) {
  const { itemKey, zone, title, chrome = "section", children } = props;
  // .ts 文件（跨扩展共享不保证 jsx-runtime）→ 用 createElement 而非 JSX 语法
  const btnBase: any = {
    background: "none", border: "none", color: "var(--text-muted, #888)", cursor: "pointer",
    fontSize: 11, lineHeight: 1, padding: "2px 5px", flexShrink: 0, fontFamily: "inherit",
  };
  return h("div", {
    "data-ext-float-dock-body": itemKey,
    "data-ext-item": itemKey,
    style: { display: "flex", flexDirection: "column", height: "100%", minHeight: 0, overflow: "hidden" },
  },
    h("div", { style: { display: "flex", alignItems: "center", gap: 4, padding: "4px 8px", borderBottom: "1px solid var(--border, #333)", flexShrink: 0 } },
      h("span", { style: { fontSize: 11, fontWeight: 600, color: "var(--text-muted, #999)", letterSpacing: "0.04em", textTransform: "uppercase", flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" as const } }, title ?? ""),
      h("button", { type: "button", title: "拉回浮窗", "aria-label": "拉回浮窗", style: btnBase, onClick: () => undockToFloat(itemKey) }, "⇲"),
      chrome === "section" && h("button", { type: "button", title: "关闭", "aria-label": "关闭", style: btnBase, onClick: () => closePanel(itemKey) }, "✕"),
    ),
    h("div", { style: { flex: 1, minHeight: 0, overflow: "hidden", display: "flex", flexDirection: "column" } }, children),
  );
}
